/*
 * 🛑 §9.5.1: "WCAG 2.2 AA for the dashboard, the default documentation theme
 * and all injected chrome, with axe reporting **zero violations in CI**."
 *
 * §17's Phase 27 exit criterion restates it: "axe reports zero WCAG 2.2 AA
 * violations."
 *
 * ## What this checks
 *
 * `resources/themes/reference-chrome.html` — §8.14.14's reference example
 * theme, rendered. It is generated by `php artisan docup:branding-reference`
 * from the real installation default theme, the real token registry and the
 * real chrome stylesheet, so this is an axe run over markup DocUp produces
 * rather than over a fixture written for the checker.
 *
 * ## 🛑 What it does NOT check, stated rather than implied
 *
 * **Colour contrast.** axe's `color-contrast` rule needs a layout engine to
 * resolve a cascaded colour, and jsdom resolves neither CSS custom properties
 * nor inheritance well enough for the answer to mean anything — it reports
 * `incomplete`, not `pass`. So the rule is **disabled here and covered
 * properly elsewhere**: §8.14.5's gate computes WCAG 2.2 contrast ratios
 * directly from the parsed token values, over a fixed matrix, in both colour
 * schemes, and refuses publication below 3:1. That is a stronger check than
 * axe-in-jsdom could be, and `ContrastGateTest` asserts the shipped default
 * theme passes every pair.
 *
 * Leaving the rule enabled and reporting its `incomplete` results as a pass
 * would be the dishonest arrangement: a green run that checked nothing.
 *
 * **Anything that needs a browser.** Focus order, keyboard traps, the
 * `prefers-reduced-motion` honouring and §8.15.8's combobox behaviour are
 * runtime properties of chrome that Phase 28 ships. They are not asserted
 * here, and the build log records that.
 */

import { readFileSync } from 'node:fs'
import { JSDOM } from 'jsdom'
import axe from 'axe-core'

const target = 'resources/themes/reference-chrome.html'

const dom = new JSDOM(readFileSync(target, 'utf8'), {
    // A URL so relative hrefs resolve; nothing is fetched.
    url: 'https://docs.example.test/',
    pretendToBeVisual: true,
    /*
     * 🛑 `outside-only`, not `dangerously`. It gives this script a
     * `window.eval` so axe can be installed on the window it audits, and it
     * does NOT execute scripts found in the document. The page under test has
     * none — §8.14.8 is the reason DocUp's chrome ships no tenant JavaScript —
     * but a checker that executed whatever it was pointed at would be a
     * checker nobody could safely point at a tenant's page later.
     */
    runScripts: 'outside-only',
})

const { window } = dom

// axe-core expects to find itself on the window it is auditing.
window.eval(axe.source)

const results = await window.axe.run(window.document, {
    runOnly: {
        type: 'tag',
        // 🛑 WCAG 2.2 AA is the target, so A and AA at 2.0, 2.1 and 2.2.
        values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'],
    },
    rules: {
        // See the header: covered by §8.14.5's own gate, not by guesswork here.
        'color-contrast': { enabled: false },
    },
})

const violations = results.violations

if (violations.length === 0) {
    const checked = results.passes.length
    process.stdout.write(`axe: 0 violations over ${target} (${checked} rules passed)\n`)
    process.exit(0)
}

process.stdout.write(`axe: ${violations.length} violation(s) over ${target}\n\n`)

for (const violation of violations) {
    process.stdout.write(`  [${violation.impact}] ${violation.id}: ${violation.help}\n`)
    process.stdout.write(`    ${violation.helpUrl}\n`)

    for (const node of violation.nodes) {
        process.stdout.write(`    at ${node.target.join(' ')}\n`)
        process.stdout.write(`      ${node.failureSummary.replace(/\n/g, '\n      ')}\n`)
    }

    process.stdout.write('\n')
}

process.exit(1)
